-- ABAR domain foundation. Idempotent and RLS-ready.
CREATE TABLE IF NOT EXISTS suppliers (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_contacts (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), supplier_id uuid NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE, name text, phone text, email text);
CREATE TABLE IF NOT EXISTS supplier_services (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), supplier_id uuid NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE, service_type text NOT NULL, details jsonb DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS supplier_requests (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), supplier_id uuid REFERENCES suppliers(id) ON DELETE SET NULL, request_type text NOT NULL, status text NOT NULL DEFAULT 'open', payload jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_quotes (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), request_id uuid NOT NULL REFERENCES supplier_requests(id) ON DELETE CASCADE, amount numeric, currency text, details jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), customer_id uuid, name text NOT NULL, mime_type text, storage_path text, status text NOT NULL DEFAULT 'pending', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS document_requests (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), customer_id uuid, document_type text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS document_versions (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE, version_no int NOT NULL, storage_path text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS secure_upload_links (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), document_request_id uuid REFERENCES document_requests(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS link_events (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), link_id uuid NOT NULL REFERENCES secure_upload_links(id) ON DELETE CASCADE, event_type text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_agents (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), name text NOT NULL, enabled boolean DEFAULT true, config jsonb DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS ai_tools (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), name text NOT NULL UNIQUE, permissions jsonb DEFAULT '[]'::jsonb, enabled boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS ai_tool_calls (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), agent_id uuid REFERENCES ai_agents(id), tool_id uuid REFERENCES ai_tools(id), conversation_id uuid REFERENCES conversations(id), status text NOT NULL, input jsonb, output jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_documents (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), title text NOT NULL, visibility text NOT NULL DEFAULT 'internal', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_versions (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), document_id uuid NOT NULL REFERENCES knowledge_documents(id) ON DELETE CASCADE, version_no int NOT NULL, content text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_chunks (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), version_id uuid NOT NULL REFERENCES knowledge_versions(id) ON DELETE CASCADE, chunk_index int NOT NULL, content text NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_embeddings (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), chunk_id uuid NOT NULL REFERENCES knowledge_chunks(id) ON DELETE CASCADE, embedding jsonb);
CREATE TABLE IF NOT EXISTS bookings (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), customer_id uuid, booking_type text NOT NULL, status text NOT NULL DEFAULT 'draft', details jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS visa_cases (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), customer_id uuid, destination text, status text NOT NULL DEFAULT 'open', details jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now());
